7a\u503c\u7528\u7a7a\u5b57\u6bb5\u6216 `NA` \u8868\u793a\u3002\n\n**\u5907\u9009\u683c\u5f0f\uff08SDF\uff09**\uff1aRDKit `SDMolSupplier` \u53ef\u76f4\u63a5\u8bfb\u53d6\uff1b\u8bbe\u8ba1\u4e2d\u4fdd\u7559\u8be5\u8def\u5f84\u4f46\u4e0d\u4f5c\u4e3a\u9ed8\u8ba4\u3002\u82e5\u6267\u884c\u73af\u5883\u65e0 RDKit\uff0cSDF \u89e3\u6790\u9000\u5316\u4e3a\u4ec5\u8bfb\u53d6 `MOL` \u5757\u4e2d\u5143\u7d20\u4e0e\u952e\u8fde\u5e76\u6620\u5c04\u56de SMILES \u5b57\u6bb5\uff0c\u4e0d\u4f5c\u4e3a\u4e3b\u8def\u5f84\u3002\n\n**\u89c4\u6a21\u5efa\u8bae**\uff1a\n- \u6f14\u793a\u6570\u636e\u96c6\uff1a**30\u201360 \u6761**\u5e38\u89c1\u5c0f\u5206\u5b50\u836f\u7269 SMILES\uff08\u8986\u76d6\u4e0d\u540c\u5206\u5b50\u91cf\u533a\u95f4\u3001\u8102\u80aa\u65cf/\u82b3\u9999\u3001\u542b/\u4e0d\u542b\u76d0\u5f62\u5f0f\uff09\uff0c\u7531\u6267\u884c\u671f\u672c\u5730\u751f\u6210\u3002\n- \u91d1\u6807\u51c6\u9a8c\u8bc1\u5b50\u96c6\uff1a**8\u201312 \u6761**\u6587\u732e\u5c5e\u6027\u503c\u5df2\u77e5\u7684\u5206\u5b50\uff08\u4e59\u9187\u3001\u963f\u53f8\u5339\u6797\u3001\u5496\u5561\u56e0\u3001\u8461\u8404\u7cd6\u7b49\uff09\uff0c\u7528\u4e8e\u7b2c 7 \u8282\u5bf9\u7167\u9a8c\u8bc1\uff0c\u53ef\u4e0e\u6f14\u793a\u6570\u636e\u96c6\u91cd\u53e0\u6216\u72ec\u7acb\u3002\n\n**\u8bb0\u5f55\u751f\u6210\u534f\u8bae\uff08\u6267\u884c\u671f\uff09**\uff1a\u82e5\u9700\u81ea\u884c\u751f\u6210\uff0c\u5219\u4ece\u9884\u7f6e\u7684\u201c\u836f\u7269 SMILES \u6e05\u5355\u201d\u5199\u5165 CSV\uff0c\u5e76\u8bb0\u5f55\u751f\u6210\u811a\u672c\u3001\u7248\u672c\u4e0e\u968f\u673a\u79cd\u5b50\u3002\n\n---\n\n## 3. \u5206\u5b50\u6027\u8d28\u6e05\u5355\u53ca\u6bcf\u9879\u7406\u7531\n\n\u9009\u62e9\u4ee5\u4e0b 7 \u7c7b\u63cf\u8ff0\u7b26\uff0c\u7406\u7531\uff1a\u5b83\u4eec\u5171\u540c\u6784\u6210 **Lipinski \u4e94\u89c4\u5219\uff08Rule of Five\uff09\u5206\u5b50\u9884\u7b5b\u63cf\u8ff0\u7b26\u96c6\u5408**\u2014\u2014\u8be5\u96c6\u5408\u662f\u88ab\u5e7f\u6cdb\u63a5\u53d7\u7684\u53e3\u670d\u7c7b\u836f\u6027\u201c\u5148\u9a8c\u201d\u6307\u6807\uff0c\u5f7c\u6b64\u8986\u76d6\u5206\u5b50\u5927\u5c0f\u3001\u8102\u6eb6\u6027\u3001\u6c22\u952e\u80fd\u529b\u3001\u6781\u6027\u8868\u9762\u79ef\u4e0e\u9aa8\u67b6\u67d4\u6027\uff0c\u8db3\u4ee5\u652f\u6491 Q2\u2013Q5 \u7684\u63cf\u8ff0\u7edf\u8ba1\u4e0e\u76f8\u5173\u5206\u6790\u3002\n\n| \u6027\u8d28 | RDKit \u63cf\u8ff0\u7b26\u540d | \u5b9a\u4e49/\u542b\u4e49 | \u5165\u9009\u7406\u7531 |\n|---|---|---|---|\n| \u5206\u5b50\u91cf | `Descriptors.MolWt` | \u6309\u5143\u7d20\u539f\u5b50\u91cf\u52a0\u548c\u7684\u5206\u5b50\u91cf\uff08g/mol\uff09 | \u5206\u5b50\u5927\u5c0f\u7684\u9996\u8981\u5ea6\u91cf\uff0cRoF \u89c4\u5219 1\uff08<500\uff09 |\n| \u8102\u6c34\u5206\u914d\u7cfb\u6570 | `Descriptors.MolLogP` | \u57fa\u4e8e\u539f\u5b50/\u5b50\u7ed3\u6784\u7684 logP \u4f30\u8ba1 | \u8102\u6eb6\u6027\u5ea6\u91cf\uff0cRoF \u89c4\u5219 2\uff08\u22645\uff09\uff0c\u4e0e\u6e17\u900f/\u6eb6\u89e3\u5ea6\u76f8\u5173 |\n| \u6c22\u952e\u4f9b\u4f53\u6570 | `Descriptors.NumHDonors` | H \u4f9b\u4f53\uff08N\u2013H\u3001O\u2013H \u7b49\uff09\u8ba1\u6570 | RoF \u89c4\u5219 3\uff08\u22645\uff09\uff0c\u5f71\u54cd\u819c\u6e17\u900f\u4e0e\u6eb6\u89e3\u5ea6 |\n| \u6c22\u952e\u53d7\u4f53\u6570 | `Descriptors.NumHAcceptors` | H \u53d7\u4f53\uff08N\u3001O \u7b49\uff09\u8ba1\u6570 | RoF \u89c4\u5219 4\uff08\u226410\uff09\uff0c\u540c\u4e0a |\n| \u62d3\u6251\u6781\u6027\u8868\u9762\u79ef | `Descriptors.TPSA` | \u6781\u6027\u539f\u5b50\u8d21\u732e\u9762\u79ef\uff08\u00c5\u00b2\uff09 | \u53e3\u670d\u5438\u6536/\u4e2d\u67a2\u6e17\u900f\u7684\u5e38\u7528\u66ff\u4ee3\u6307\u6807\uff08\u53c2\u8003\u9608\u503c ~140 \u00c5\u00b2\uff09 |\n| \u82b3\u9999\u73af\u6570 / \u603b\u73af\u6570 | `Descriptors.NumAromaticRings` / `Descriptors.RingInfo.NumRings()` | \u82b3\u9999\u73af\u4e0e\u5168\u90e8\u73af\u8ba1\u6570 | \u9aa8\u67b6\u590d\u6742\u5ea6\u3001\u5e73\u9762\u6027\u76f8\u5173\uff0c\u5f71\u54cd\u7c7b\u836f\u7a7a\u95f4 |\n| \u53ef\u65cb\u8f6c\u952e\u6570 | `Descriptors.NumRotatableBonds` | \u5141\u8bb8\u65cb\u8f6c\u7684\u975e\u73af\u5355\u952e\u6570 | \u6784\u8c61\u67d4\u97e7\u6027\u6307\u6807\uff0c\u7c7b\u836f\u7b5b\u9009\u5e38\u7528\uff08\u53c2\u8003\u9608\u503c \u226410\uff09 |\n\n**\u6d3e\u751f\u6c47\u603b\u6307\u6807**\uff1aLipinski \u901a\u8fc7\u6807\u8bb0\uff08MW<500 \u4e14 logP\u22645 \u4e14 HBD\u22645 \u4e14 HBA\u226410 \u540c\u65f6\u6210\u7acb\uff09\uff0c\u4f5c\u4e3a Q4 \u7684\u6c47\u603b\u8f93\u51fa\u3002\n\n---\n\n## 4. \u5de5\u5177\u4e0e\u53ef\u884c\u6027\u53cc\u8f68\n\n### 4.1 \u9996\u9009\u8def\u5f84\uff08RDKit\uff09\n- \u4f7f\u7528 `rdkit.Chem`\uff08`MolFromSmiles` \u89e3\u6790/\u6d88\u6bd2\uff09\u3001`rdkit.Chem.Descriptors`\uff08\u8868 3 \u5404\u63cf\u8ff0\u7b26\uff09\u3001`rdkit.Chem.Lipinski`\u3002\n- \u8f93\u51fa\u4e3a\u6bcf\u6761\u8bb0\u5f55\u4e00\u4e2a\u63cf\u8ff0\u7b26\u5411\u91cf\uff08CSV/JSON \u843d\u5730\uff09\u3002\n\n### 4.2 \u5f53\u524d\u6c99\u7bb1\u5b9e\u6d4b\u72b6\u6001\uff08\u91cd\u8981\u3001\u5fc5\u987b\u5982\u5b9e\u62ab\u9732\uff09\n- \u7cfb\u7edf Python **3.14.4**\uff1b`rdkit`/`pandas`/`numpy`/`scipy`/`matplotlib` **\u5168\u90e8\u4e0d\u53ef\u7528**\uff08`ModuleNotFoundError`\uff09\u3002\n- **\u7f51\u7edc\u7981\u7528**\uff0c`pip download`/`pip install` \u5747\u5931\u8d25\uff08\u79bb\u7ebf\uff0c\u65e0\u6cd5\u8865\u88c5\uff09\u3002\n- \u5df2\u5b9e\u6d4b\u53ef\u7528\uff1a\u6807\u51c6\u5e93 `csv`\u3001`json`\u3001`re`\u3001`math`\u3001`collections`\u3001`statistics`\uff08\u542b `mean/median/stdev/variance/quantiles`\uff0c\u53ef\u7b97\u56db\u5206\u4f4d\u4e0e IQR\uff09\u3002\n\n### 4.3 \u7eaf\u6807\u51c6\u5e93\u964d\u7ea7\u8def\u5f84\uff08\u82e5\u6267\u884c\u73af\u5883\u4ecd\u65e0 RDKit\uff09\n\u7528 stdlib \u5b9e\u73b0\u201c\u7b80\u5316 SMILES \u89e3\u6790 + \u542f\u53d1\u5f0f\u63cf\u8ff0\u7b26\u201d\uff0c\u5e76**\u9010\u9879\u5982\u5b9e\u6807\u6ce8\u53ef\u8ba1\u7b97\u6027**\uff1a\n- \u5206\u5b50\u91cf\uff1a\u6309 SMILES \u4e2d\u539f\u5b50\u7b26\u53f7\u7d2f\u52a0\u539f\u5b50\u91cf\uff08\u5904\u7406\u62ec\u53f7\u3001\u73af\u95ed\u5408\u3001\u7535\u8377\u3001\u540c\u4f4d\u7d20\u53ef\u5ffd\u7565\uff09\u2014\u2014**\u53ef\u8ba1\u7b97\uff08\u7cbe\u786e\uff0c\u57fa\u4e8e\u539f\u5b50\u7c7b\u578b\uff09**\u3002\n- \u6c22\u952e\u4f9b\u4f53/\u53d7\u4f53\uff1a\u57fa\u4e8e\u5e38\u89c1\u5b98\u80fd\u56e2/\u539f\u5b50\u73af\u5883\u7684\u542f\u53d1\u5f0f\u8ba1\u6570\uff08\u5982\u8fde H \u7684 N/O \u4e3a\u4f9b\u4f53\uff0csp2 N / \u53cc\u952e O \u4e3a\u53d7\u4f53\uff09\u2014\u2014**\u8fd1\u4f3c**\uff0c\u6807\u6ce8\u4e3a\u542f\u53d1\u5f0f\u800c\u975e RDKit \u5b9a\u4e49\u3002\n- \u73af\u6570\uff1a\u57fa\u4e8e\u73af\u95ed\u5408\u6570\u5b57\u6807\u8bb0\u4e0e\u82b3\u9999\u7b26\uff08\u5c0f\u5199 `c`\uff09\u7684\u7b80\u5316\u8ba1\u6570\u2014\u2014**\u8fd1\u4f3c**\u3002\n- \u53ef\u65cb\u8f6c\u952e\uff1a\u8bc6\u522b\u975e\u73af\u3001\u975e\u672b\u7aef\u5355\u952e\uff08\u975e\u53cc/\u4e09\u952e\u3001\u4e0d\u5728\u73af\u5185\uff09\u2014\u2014**\u8fd1\u4f3c**\u3002\n- **logP \u4e0e TPSA\uff1a\u65e0 RDKit \u65f6\u53ea\u6709\u8fd1\u4f3c\u5b50\u7ed3\u6784\u52a0\u548c\u6216**\u4e0d\u53ef\u7cbe\u786e\u8ba1\u7b97**\u2014\u2014\u8bbe\u8ba1\u4e2d\u660e\u786e\u62ab\u9732\u4e3a\u964d\u7ea7\u9879\uff0c\u8f93\u51fa\u6807\u6ce8 `approx` \u6216 `NA`\uff0c\u4e0d\u89c6\u4e3a\u7f3a\u9677\uff08\u6b64\u4e3a\u672c\u8bbe\u8ba1\u5df2\u62ab\u9732\u7684\u964d\u7ea7\u8def\u5f84\uff09\u3002\n\n### 4.4 \u7edf\u8ba1\u5206\u6790\u5de5\u5177\u964d\u7ea7\n- \u65e0 numpy/scipy\uff1a\u63cf\u8ff0\u7edf\u8ba1\u3001\u56db\u5206\u4f4d/IQR\u3001Pearson/Spearman \u76f8\u5173\u3001Mann-Whitney U \u5747\u9700**\u81ea\u5b9e\u73b0**\uff08Pearson/Spearman \u516c\u5f0f\u4e3a\u51e0\u5341\u884c\u7eaf Python\uff1bMann-Whitney U \u7528\u6392\u5e8f\u79e9\u548c\u5b9e\u73b0\uff0c\u89c4\u6a21 \u2264500 \u6761\u5b8c\u5168\u53ef\u884c\uff09\u3002\n- \u65e0 matplotlib\uff1a\u7ed8\u56fe\u964d\u7ea7\u4e3a\u6587\u672c/CSV \u6c47\u603b + **ASCII \u76f4\u65b9\u56fe**\uff08\u7528 `#` \u5b57\u7b26\u6309\u5206\u7bb1\u8ba1\u6570\u7ed8\u5236\uff09\u3002\n\n---\n\n## 5. \u6570\u636e\u6e05\u6d17\u4e0e\u8d28\u63a7\uff08QC\uff09\n\n\u6309\u987a\u5e8f\u6267\u884c\u5e76\u5168\u7a0b\u8f93\u51fa QC \u65e5\u5fd7\uff08\u6bcf\u4e2a\u6b65\u9aa4\u7684\u8f93\u5165/\u8f93\u51fa\u8bb0\u5f55\u6570\uff09\uff1a\n1. **\u7ed3\u6784\u6821\u9a8c**\uff1a\u9010\u5217\u7c7b\u578b\u68c0\u67e5\uff1b`smiles` \u4e3a\u7a7a\u6216\u975e\u5b57\u7b26\u4e32\u7684\u8bb0\u5f55\u5254\u9664\u3002\n2. **SMILES \u53ef\u89e3\u6790\u6027\u6821\u9a8c**\uff1a\n   - RDKit \u8def\u5f84\uff1a`MolFromSmiles(smiles)` \u8fd4\u56de `None` \u5373\u5931\u8d25\u3002\n   - \u964d\u7ea7\u8def\u5f84\uff1a\u81ea\u5b9a\u4e49\u89e3\u6790\u5668 try/except\uff0c\u62ec\u53f7\u4e0d\u5339\u914d\u3001\u975e\u6cd5\u5143\u7d20\u7b49\u8bb0\u4e3a\u5931\u8d25\u3002\n   - \u8bb0\u5f55\u5931\u8d25\u8ba1\u6570\u5e76\u8ba1\u7b97**\u5931\u8d25\u7387**\uff08\u5931\u8d25\u6570/\u603b\u8bb0\u5f55\u6570\uff09\uff0c\u5931\u8d25\u8bb0\u5f55\u5355\u72ec\u5bfc\u51fa\u4f9b\u4eba\u5de5\u590d\u6838\u3002\n3. **\u89c4\u8303\u5316\u4e0e\u53bb\u91cd**\uff1a\n   - RDKit\uff1a\u8f93\u51fa `Chem.MolToSmiles(mol)` \u89c4\u8303 SMILES\uff0c\u6309\u89c4\u8303 SMILES\uff08\u6216 InChIKey\uff09\u53bb\u91cd\u3002\n   - \u964d\u7ea7\u8def\u5f84\uff1a\u6309\u6e05\u6d17\u540e SMILES \u5b57\u7b26\u4e32\u53bb\u91cd\uff0c\u5e76\u6807\u6ce8\u201c\u672a\u505a\u5b8c\u6574\u89c4\u8303\u5316\u201d\u3002\n   - \u62a5\u544a\u53bb\u91cd\u524d\u540e\u8bb0\u5f55\u6570\u3002\n4. **\u76d0/\u6297\u8861\u79bb\u5b50\u5904\u7406\uff08\u53ef\u9009\uff09**\uff1aRDKit \u7528 `MolFragmentToSmiles` \u6216\u53bb\u76d0\u5de5\u5177\u53d6\u5206\u5b50\u9aa8\u67b6\u6309\u9aa8\u67b6\u53bb\u91cd\uff1b\u964d\u7ea7\u8def\u5f84\u8df3\u8fc7\u5e76\u5728\u6587\u6863\u6807\u6ce8\u8be5\u6b65\u672a\u6267\u884c\u3002\n5. **\u7f3a\u5931\u503c\u7edf\u8ba1\u4e0e\u8986\u76d6\u7387\u62a5\u544a**\uff1a\u8f93\u51fa\u6bcf\u4e2a\u63cf\u8ff0\u7b26\u7684\u53ef\u7528\u8bb0\u5f55\u6570\u3001\u7f3a\u5931\u6570\u3001\u7f3a\u5931\u7387\uff08\u8986\u76d6\u7387\u8868\uff09\u3002\n6. **QC \u51b3\u7b56\u53c2\u6570**\uff1a\u8bb0\u5f55\u5168\u90e8\u9608\u503c\uff08\u5982\u89e3\u6790\u5931\u8d25\u7387\u4e0a\u9650\u544a\u8b66\u7ebf\u3001\u53bb\u76d0\u5f00\u5173\u3001\u63d2\u8865\u5f00\u5173\uff09\u4f9b\u590d\u73b0\u3002\n\n---\n\n## 6. \u5206\u6790\u8ba1\u5212\n\n1. **\u63cf\u8ff0\u7edf\u8ba1**\uff1a\u6bcf\u4e2a\u63cf\u8ff0\u7b26\u8f93\u51fa n\u3001\u5747\u503c\u3001\u4e2d\u4f4d\u6570\u3001\u56db\u5206\u4f4d\uff08Q1/Q3\uff0c\u7528 `statistics.quantiles(..., n=4)`\uff09\u3001min/max\u3001\u6807\u51c6\u5dee\u3001\u65b9\u5dee\u3001\u504f\u5ea6\u3001\u5cf0\u5ea6\uff08\u504f\u5ea6/\u5cf0\u5ea6\u964d\u7ea7\u8def\u5f84\u81ea\u884c\u5b9e\u73b0\uff09\u3002\n2. **\u5206\u5e03\u4e0e\u5f02\u5e38\u503c**\uff1a\u76f4\u65b9\u56fe\uff08\u6216 ASCII \u76f4\u65b9\u56fe\uff09\u53ef\u89c6\u5316\u5206\u5e03\u5f62\u6001\uff1b\u5f02\u5e38\u503c\u7528 **IQR \u6cd5**\uff08< Q1 \u2212 1.5\u00d7IQR \u6216 > Q3 + 1.5\u00d7IQR\uff09\u4e0e **z-score \u6cd5**\uff08|z|>3\uff0c\u9700\u81ea\u5b9e\u73b0\uff09\u53cc\u6cd5\u68c0\u6d4b\u5e76\u62a5\u544a\u4ea4\u96c6/\u5dee\u5f02\u3002\n3. **\u7f3a\u5931\u5904\u7406**\uff1a\u4ee5**\u8bb0\u5f55\u7ea7\u6392\u9664\uff08complete-case\uff09\u4e3a\u4e3b**\uff1b\u82e5\u67d0\u63cf\u8ff0\u7b26\u7f3a\u5931\u4ec5\u5c5e\u53ef\u63a5\u53d7\u6bd4\u4f8b\uff08\u9884\u7f6e\u9608\u503c\uff0c\u5efa\u8bae <10%\uff09\uff0c\u4e0d\u63d2\u8865\uff1b\u82e5\u5fc5\u987b\u63d2\u8865\uff0c\u5219\u4ec5\u7528**\u4e2d\u4f4d\u6570\u63d2\u8865**\u5e76\u5728\u8f93\u51fa\u4e2d\u6807\u6ce8\u201c\u5df2\u63d2\u8865\u201d\u5217\u4e0e\u63d2\u8865\u7387\u3002\u8bbe\u8ba1\u5185\u4e0d\u5f15\u5165\u590d\u6742\u63d2\u8865\u6a21\u578b\u3002\n4. **\u6027\u8d28\u95f4\u76f8\u5173**\uff1a\u8ba1\u7b97 **Pearson** \u4e0e **Spearman** \u76f8\u5173\u77e9\u9635\uff1b\u91cd\u70b9\u68c0\u67e5\u9884\u671f\u5173\u7cfb\uff08MW\u2194\u53ef\u65cb\u8f6c\u952e\u6b63\u76f8\u5173\u3001TPSA\u2194HBA \u6b63\u76f8\u5173\u3001logP \u4e0e TPSA \u8d1f\u76f8\u5173\u8d8b\u52bf\uff09\uff1b\u65e0 pandas \u65f6\u7528\u7eaf Python \u5b9e\u73b0\uff08\u89c4\u6a21 \u2264500 \u65e0\u6027\u80fd\u95ee\u9898\uff09\u3002\u8f93\u51fa\u70ed\u529b\u56fe\u6216\u6587\u672c\u77e9\u9635/CSV\u3002\n5. **\u5206\u7ec4\u6bd4\u8f83\uff08\u6761\u4ef6\u6027\uff0cQ5\uff09**\uff1a\u4ec5\u5f53\u6570\u636e\u542b `category`/`activity_label` \u5b57\u6bb5\u65f6\u6267\u884c\u3002\u8bbe\u8ba1\u5185**\u56fa\u5b9a\u68c0\u9a8c\u9009\u62e9**\uff1a\u5148 Levene \u68c0\u9a8c\uff08\u81ea\u5b9e\u73b0\uff09\u5224\u65ad\u65b9\u5dee\u9f50\u6027\u2014\u2014\u65b9\u5dee\u9f50\u7528 **Welch t \u68c0\u9a8c**\uff0c\u4e0d\u9f50\u6216\u6837\u672c\u91cf\u5c0f/\u975e\u6b63\u6001\u7528 **Mann-Whitney U \u68c0\u9a8c**\uff1b\u591a\u7ec4\u65f6\u7528 Kruskal-Wallis \u521d\u7b5b\u540e\u505a\u4e24\u4e24 Mann-Whitney U \u5e76 Benjamini-Hochberg \u6821\u6b63\u3002\u5168\u90e8\u4e3a\u8bbe\u8ba1\u5185\u56fa\u5b9a\u9009\u62e9\uff0c\u4e0d\u4e8b\u540e\u6311\u9009\u3002\n6. **Lipinski \u901a\u8fc7\u7387\u6c47\u603b\uff08Q4\uff09**\uff1a\u6309\u7b2c 3 \u8282\u6d3e\u751f\u6307\u6807\u7edf\u8ba1\u901a\u8fc7/\u4e0d\u901a\u8fc7\u53ca\u5404\u81ea\u5360\u6bd4\uff0c\u5e76\u7ec6\u5206\u6bcf\u6761 RoF \u89c4\u5219\u7684\u5355\u72ec\u8fdd\u53cd\u7387\u3002\n\n---\n\n## 7. \u5bf9\u7167\u4e0e\u9a8c\u8bc1\n\n1. **\u91d1\u6807\u51c6\u9a8c\u8bc1\u5b50\u96c6**\uff1a8\u201312 \u6761\u6587\u732e\u503c\u5df2\u77e5\u5206\u5b50\uff08\u4e59\u9187\u3001\u963f\u53f8\u5339\u6797\u3001\u5496\u5561\u56e0\u3001\u8461\u8404\u7cd6\u7b49\uff09\uff0c\u8ba1\u7b97\u540e\u4e0e\u5176\u6587\u732e\u503c\u5bf9\u7167\uff0c\u9010\u63cf\u8ff0\u7b26\u62a5\u544a**\u76f8\u5bf9\u504f\u5dee/\u7edd\u5bf9\u504f\u5dee**\uff1b\u504f\u5dee\u8d85\u9608\u503c\uff08\u9884\u7f6e\uff0c\u5982 MW<1%\u3001\u8fd1\u4f3c\u63cf\u8ff0\u7b26\u5141\u8bb8\u66f4\u5927\u7684\u660e\u786e\u5bb9\u5dee\uff09\u5219\u5224\u5b9a\u8be5\u63cf\u8ff0\u7b26\u8ba1\u7b97\u901a\u9053\u5b58\u5728\u95ee\u9898\u3001\u9700\u4eba\u5de5\u590d\u6838\u3002\n2. **RDKit \u4e0e\u7eaf stdlib \u53cc\u901a\u9053\u4ea4\u53c9\u6838\u5bf9\uff08\u53ef\u6267\u884c\u65f6\uff09**\uff1a\u540c\u4e00\u6570\u636e\u96c6\u5206\u522b\u8d70 RDKit \u4e0e\u964d\u7ea7\u5b9e\u73b0\uff0c\u5bf9\u53ef\u7cbe\u786e\u8ba1\u7b97\u7684\u63cf\u8ff0\u7b26\uff08\u81f3\u5c11 MW\uff09\u6bd4\u5bf9\u4e00\u81f4\u6027\uff0c\u91cf\u5316\u542f\u53d1\u5f0f\u4e0e\u7cbe\u786e\u503c\u5dee\u8ddd\uff0c\u5e76\u636e\u6b64\u5728\u8f93\u51fa\u6587\u6863\u6807\u6ce8\u964d\u7ea7\u8def\u5f84\u7684\u7f6e\u4fe1\u5ea6\u3002\n3. **\u53ef\u590d\u73b0\u6027**\uff1a\u56fa\u5b9a\u968f\u673a\u79cd\u5b50\uff08\u5982\u6570\u636e\u62bd\u6837/\u751f\u6210 seed=42\uff09\uff1b\u8bb0\u5f55 Python \u7248\u672c\u3001RDKit \u7248\u672c\uff08\u82e5\u6709\uff09\u3001QC \u53c2\u6570\u4e0e\u63d2\u8865\u5f00\u5173\uff1b\u8f93\u51fa\u539f\u59cb+\u6e05\u6d17\u540e\u6570\u636e\u3001\u63cf\u8ff0\u7b26\u8868\u3001QC \u65e5\u5fd7\u4e0e\u5206\u6790\u811a\u672c\u7248\u672c\uff0c\u786e\u4fdd\u53ef\u91cd\u65b0\u751f\u6210\u5168\u90e8\u7ed3\u679c\u3002\n4. **\u786e\u5b9a\u6027\u58f0\u660e**\uff1a\u4ee5\u4e0a\u4e3a\u8bbe\u8ba1\u4e2d\u7684\u5bf9\u7167\u8bbe\u7f6e\uff0c**\u672a\u6267\u884c**\uff1b\u9a8c\u8bc1\u73af\u8282\u5728\u5b9e\u9a8c\u6267\u884c\u9636\u6bb5\u5b8c\u6210\u3002\n\n---\n\n## 8. \u53ef\u884c\u6027\u8bc4\u4f30\n\n- **\u8ba1\u7b97\u89c4\u6a21\u53ef\u884c\u6027**\uff1a\u6f14\u793a\u6570\u636e\u96c6 30\u201360 \u6761\uff0c\u8bbe\u8ba1\u76ee\u6807\u653e\u5bbd\u5230 **50\u2013500 \u6761**\u3002RDKit \u4e0b\u6bcf\u6761\u63cf\u8ff0\u7b26\u8ba1\u7b97\u4e3a\u6beb\u79d2\u7ea7\uff0c\u603b\u8017\u65f6\u79d2\u7ea7\uff1b\u7eaf stdlib \u89e3\u6790 + \u63cf\u8ff0\u7b26\u542f\u53d1\u5f0f\u540c\u4e3a\u79d2\u7ea7\uff1b\u63cf\u8ff0\u7edf\u8ba1/\u76f8\u5173\u5728 500 \u6761\u89c4\u6a21\u4e0b\u65e0\u6027\u80fd\u74f6\u9888\uff08\u7eaf Python \u8db3\u591f\uff09\u3002\n- **\u7ed8\u56fe\u964d\u7ea7\u53ef\u884c\u6027**\uff1a\u65e0 matplotlib \u65f6\uff0c\u76f4\u65b9\u56fe/\u70ed\u529b\u4fe1\u606f\u4ee5\u6587\u672c/CSV \u6c47\u603b + **ASCII \u76f4\u65b9\u56fe**\u8f93\u51fa\uff0c\u4fdd\u8bc1\u5206\u6790\u7ed3\u679c\u53ef\u8bfb\u4e14\u53ef\u843d\u5730\u3002\n- **\u6574\u4f53\u53ef\u884c\u6027**\uff1a\u9ad8\u3002\u6838\u5fc3\u6d41\u7a0b\uff08\u89e3\u6790\u2192QC\u2192\u63cf\u8ff0\u7edf\u8ba1\u2192\u76f8\u5173\u2192\u5206\u7ec4\u2192RoF \u6c47\u603b\uff09\u5728 RDKit \u53ef\u7528\u65f6\u5168\u81ea\u52a8\u5b8c\u6210\uff1b\u5728\u7eaf stdlib \u73af\u5883\u4e0b\u4ee5\u201c\u90e8\u5206\u7cbe\u786e + \u90e8\u5206\u8fd1\u4f3c/NA\u201d\u7684\u964d\u7ea7\u8f93\u51fa\u4ecd\u53ef\u56de\u7b54 Q1\u2013Q5\uff08Q5 \u89c6\u5b57\u6bb5\u800c\u5b9a\uff09\u3002\n- **\u6700\u5927\u98ce\u9669\uff08\u660e\u786e\u62ab\u9732\uff09**\uff1a\n  - \u98ce\u9669 1\uff1a\u6267\u884c\u73af\u5883\u65e0 RDKit \u4e14\u65e0\u6cd5\u5b89\u88c5\uff08\u5f53\u524d\u6c99\u7bb1\u5df2\u5b9e\u6d4b\u5982\u6b64\uff09\u2014\u2014\u5bf9\u7b56\u4e3a\u964d\u7ea7\u8def\u5f84\uff0c\u5e76\u5c06 logP/TPSA \u6807\u6ce8\u4e3a\u8fd1\u4f3c/\u4e0d\u53ef\u8ba1\u7b97\u3002\n  - \u98ce\u9669 2\uff1alogP/TPSA \u5728\u964d\u7ea7\u8def\u5f84\u4e0b\u7cbe\u5ea6\u6709\u9650\u6216\u7f3a\u5931\u2014\u2014\u8bbe\u8ba1\u4e2d\u5df2\u660e\u786e\u4e3a\u5df2\u62ab\u9732\u964d\u7ea7\uff0c\u4e0d\u7b97\u7f3a\u9677\uff1b\u6587\u6863\u7528 `approx`/`NA` \u6807\u6ce8\u3002\n  - \u98ce\u9669 3\uff1a\u65e0\u6570\u636e\u96c6\u6587\u4ef6\u2014\u2014\u5bf9\u7b56\u4e3a\u6267\u884c\u671f\u6309\u7b2c 2 \u8282\u534f\u8bae\u672c\u5730\u751f\u6210\u793a\u4f8b CSV\u3002\n  - \u98ce\u9669 4\uff1a\u6570\u636e\u65e0 category/activity \u5b57\u6bb5\u2014\u2014Q5 \u76f8\u5e94\u53d8\u4e3a\u201c\u4e0d\u6267\u884c\uff08\u6570\u636e\u4e0d\u652f\u6301\uff09\u201d\uff0c\u5176\u4f59\u95ee\u9898\u4e0d\u53d7\u5f71\u54cd\u3002\n\n---\n\n## 9. \u5173\u952e\u5047\u8bbe\u4e0e\u4e0d\u786e\u5b9a\u6027\uff08\u539f\u6837\u4fdd\u7559\u5e76\u6ce8\u660e\u6027\u8d28\uff09\n\n\u4ee5\u4e0b\u6bcf\u9879\u5747\u4e3a**\u5047\u5b9a\uff08assumption\uff09\uff0c\u975e\u5df2\u8bc1\u5b9e\u7684\u4e8b\u5b9e**\uff0c\u6267\u884c\u524d\u9700\u6838\u9a8c\uff1a\n\n1. **\u5047\u8bbe A**\uff1a\u6267\u884c\u73af\u5883\u5c06\u5177\u5907 RDKit\u300